import 'package:flutter/material.dart';import 'package:platform_core_frontend/features/super_admin/data/super_admin_repository.dart';import 'package:platform_core_frontend/features/super_admin/models/admin_user_model.dart';import 'package:platform_core_frontend/features/super_admin/presentation/users/widgets/assign_roles_dialog.dart';import 'package:platform_core_frontend/features/super_admin/presentation/users/widgets/update_user_status_dialog.dart';import 'package:platform_core_frontend/features/super_admin/presentation/widgets_common.dart';import 'package:platform_core_frontend/shared/widgets/loading_view.dart';
class AdminUserDetailScreen extends StatefulWidget{const AdminUserDetailScreen({super.key,required this.id,this.initial});final String id;final AdminUserModel? initial;@override State<AdminUserDetailScreen> createState()=>_S();}class _S extends State<AdminUserDetailScreen>{final repo=SuperAdminRepository();late Future<AdminUserModel> f=repo.getUser(widget.id);@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('User Details')),body:FutureBuilder(future:f,initialData:widget.initial,builder:(c,s){if(!s.hasData)return const LoadingView();final u=s.data!;return ListView(padding:const EdgeInsets.all(16),children:[AdminStatusChip(u.status),InfoRow('Name',u.fullName),InfoRow('Phone',u.phone),InfoRow('Email',u.email),InfoRow('Roles',u.roles.join(', ')),InfoRow('Masjid',u.masjidName??u.masjidId),InfoRow('Created',u.createdAt),const SizedBox(height:16),Wrap(spacing:12,children:[FilledButton(onPressed:()async{final st=await showUpdateUserStatusDialog(c);if(st!=null){await repo.updateUserStatus(u.id,st);setState(()=>f=repo.getUser(widget.id));}},child:const Text('Change Status')),FilledButton(onPressed:()async{final roles=await showAssignRolesDialog(c,u.roles);if(roles!=null){await repo.updateUserRoles(u.id,roles);setState(()=>f=repo.getUser(widget.id));}},child:const Text('Assign Roles'))])]);}));}
